void initFromVendRFQJour(VendRFQJour _vendRFQJour)
{
    next initFromVendRFQJour(_vendRFQJour);

    this.AVACashDisc    = _vendRFQJour.CashDisc;
    this.AVAPayment     = _vendRFQJour.Payment;
    this.AVARequester   = _vendRFQJour.Requester;
    this.AVAVendEmail   = _vendRFQJour.Email;
    this.AVARFQCaseId   = _vendRFQJour.RFQCaseId;
}
